import{z as s,x as B,o as t,c as p,q as A,j as i,D as e,d as l,s as r,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"面涂与浸出","description":"","frontmatter":{"title":"面涂与浸出","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/topcoat-leaching.md","filePath":"litho/topcoat-leaching.md","lastUpdated":1791063341000}'),d={name:"litho/topcoat-leaching.md"};function h(m,a,c,C,D,P){const o=B("Mermaid");return t(),p("div",null,[a[2]||(a[2]=A('<h1 id="面涂与浸出" tabindex="-1">面涂与浸出 <a class="header-anchor" href="#面涂与浸出" aria-label="Permalink to &quot;面涂与浸出&quot;">​</a></h1><div class="epigraph"><p>水膜贴着胶走，PAG 和淬灭剂会溶出去：污染最后一片镜头，也改局部化学。面涂是隔离层；后来的无面涂胶则把隔离写进配方。</p><footer>—— 据浸没胶化学的公开讨论：leaching、topcoat、以及后继的 topcoat-less 路线</footer></div><p><a href="/litho/immersion-defects">上一课</a>把气泡和水印写成弯月面失稳的形貌。缺口是即使液膜几何合格，胶里的小分子仍会进入水。<a href="/litho/car-resist">CAR</a> 的 PAG 与淬灭剂在 ArF 上本就有出气与污染账；浸没把接触从「气–胶」换成「水–胶」，浸出（leaching）成为镜头寿命和缺陷的慢变量。本课钉面涂与浸出。更高折射率的浸没液把隔离账翻成什么样，留给<a href="/litho/high-n-immersion">下一课</a>；离轴照明如何压 \\(k_1\\)，在后面的<a href="/litho/off-axis-illumination">离轴照明与偶极/四极光瞳</a>课上另起，不在这里改光瞳。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>水是极性介质。离子型 PAG、淬灭剂和小分子添加剂会在秒级扫描接触里溶出。后果有两头：水被污染，回收系统与镜头最后表面吃有机物和酸；胶表层贫 PAG，局部灵敏度与 \\(\\gamma\\) 变，窗口边沿先出现桥连或残胶。公开的浸没胶讨论把 leaching 列为必须被面涂或配方挡住的项，而不是可选项。头再稳，也挡不住分配系数。</p><p>缺口是化学隔离，不是再设计一个头。头可以除泡，除不掉分子扩散。水印会把已浸出的溶质浓缩，上一课的干燥斑与本课的浸出在缺陷图上可以叠在一起，分析要拆。</p><h3 id="面涂不是-barc-的顶配" tabindex="-1">面涂不是 BARC 的顶配 <a class="header-anchor" href="#面涂不是-barc-的顶配" aria-label="Permalink to &quot;面涂不是 BARC 的顶配&quot;">​</a></h3><p>BARC / EUV 底层在胶下，管反射、黏附、二次电子。面涂（topcoat）在胶上，浸没时代首先为了挡水、控接触角、挡浸出。光学上它是一层额外薄膜，有厚度和折射率，会进驻波与剂量；功能上它不是抗反射的别名。把底层和面涂写成「上下各涂一次 BARC」，栈会乱。</p><p><span class="marginnote">面涂要在显影前去掉或能被显影液兼容。残留面涂当残胶报，会把轨道问题写成曝光不足。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>早期量产多用疏水面涂：旋涂在 CAR 上，提供接触角窗口给浸没头，并当 PAG 的扩散垒。代价是多一步涂烘、缺陷源多一层、光学模型多一张膜。后续公开路线是 topcoat-less：聚合物疏水基团和低浸出 PAG 把隔离做进胶，减少轨道步骤。两种都要测浸出（水中分析 PAG/阴离子）和镜头污染加速，本课不引用未公开的 ng 级合同值，只保留：有合格线，而且必须和水温、接触时间一起报。</p><p>换胶或换面涂，浸没头的接触角窗口要重验证，否则上一课的气泡水印会反弹。OPC 紧凑模型要含顶膜；漏掉面涂厚度，剂量轴会系统性偏。</p><p>水质分析要进短环，不能只在换胶资格认证时测一次。</p><h3 id="与出气课的分工" tabindex="-1">与出气课的分工 <a class="header-anchor" href="#与出气课的分工" aria-label="Permalink to &quot;与出气课的分工&quot;">​</a></h3><p>干式 ArF 的上层涂层更多为了控出气打镜头。浸没面涂身兼出气、浸出、浸润三角。EUV 真空没有液膜，浸出语言不要搬过去；EUV 出气仍在，但是另一课程的氢与多层膜。</p>',15)),(t(),i(n,null,{default:e(()=>[r(o,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20PAG%5B%22PAG%20%2F%20%E6%B7%AC%E7%81%AD%E5%89%82%22%5D%20--%3E%20LEACH%5B%22%E6%BA%B6%E5%85%A5%E6%B0%B4%E8%86%9C%22%5D%0A%20%20LEACH%20--%3E%20LENS%5B%22%E6%9C%80%E5%90%8E%E5%85%83%E4%BB%B6%E6%B1%A1%E6%9F%93%22%5D%0A%20%20LEACH%20--%3E%20CHEM%5B%22%E8%A1%A8%E5%B1%82%E8%B4%AB%E5%8C%96%20%2F%20%E5%B1%80%E9%83%A8%20%CE%B3%22%5D%0A%20%20TC%5B%22%E9%9D%A2%E6%B6%82%E6%88%96%E9%85%8D%E6%96%B9%E9%9A%94%E7%A6%BB%22%5D%20--%3E%20LEACH%0A%20%20TC%20--%3E%20CA%5B%22%E6%8E%A5%E8%A7%A6%E8%A7%92%20%E2%86%92%20%E5%BC%AF%E6%9C%88%E9%9D%A2%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[l("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"浸出是近表面扩散加分配：接触时间由扫描速度和头内停留决定，速度越慢往往溶得越多，与产能旋钮打架。表层贫 PAG 使正胶局部欠敏，CD 偏大或清不干净；淬灭剂若先溶，阈值也会动。污染端，溶出物在镜头表面形成吸收膜，193 nm 很疼，透射和焦面慢漂，看起来像设备老化。清洗与换件是维护，不是光学重新设计。",-1)),a[5]||(a[5]=E("p",null,"疏水面涂把接触角推到头的设计窗，弯月面更稳，水印下降——流体课与化学课在此交汇。过疏则可能黏附差、面涂缺陷升。工作点是浸润与隔离的折中，不是越疏越好。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"分配系数可以类比泡茶：茶叶里的物质有多少溶进水，取决于它「在水里舒不舒服」。PAG 若更愿意待在水里，溶出就快，胶表层被掏空——头再稳也拦不住分子自己做选择。")],-1)),a[7]||(a[7]=E("p",null,[E("span",{class:"marginnote"},"为什么污染端容易误诊：浸出物在镜头表面长吸收膜，透射缓降、焦面慢漂，症状与镜头老化几乎一样。先查短环里的水质分析，再决定要不要动镜头，能省一次不必要的大修。")],-1)),(t(),i(n,null,{default:e(()=>[r(o,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E6%B0%B4%E8%86%9C%E6%8E%A5%E8%A7%A6%22%5D%20--%3E%20DIF%5B%22%E8%BF%91%E8%A1%A8%E9%9D%A2%E6%89%A9%E6%95%A3%20%2B%20%E5%88%86%E9%85%8D%E7%B3%BB%E6%95%B0%22%5D%0A%20%20T%5B%22%E6%8E%A5%E8%A7%A6%E6%97%B6%E9%97%B4%3A%20%E6%89%AB%E6%8F%8F%E9%80%9F%E5%BA%A6%E4%B8%8E%E5%81%9C%E7%95%99%22%5D%20--%3E%20DIF%0A%20%20DIF%20--%3E%20PAG%5B%22%E8%A1%A8%E5%B1%82%E8%B4%AB%20PAG%20%E4%B8%8E%E6%B7%AC%E7%81%AD%E5%89%82%22%5D%0A%20%20PAG%20--%3E%20CD%5B%22%E5%B1%80%E9%83%A8%E6%AC%A0%E6%95%8F%3A%20CD%20%E5%81%8F%20%2F%20%E6%AE%8B%E8%83%B6%22%5D%0A%20%20DIF%20--%3E%20POL%5B%22%E6%B0%B4%E4%B8%AD%E6%BA%B6%E5%87%BA%E7%89%A9%22%5D%0A%20%20POL%20--%3E%20LENS%5B%22%E9%95%9C%E5%A4%B4%E8%A1%A8%E9%9D%A2%E5%90%B8%E6%94%B6%E8%86%9C%22%5D%0A%20%20LENS%20--%3E%20DR%5B%22%E9%80%8F%E5%B0%84%E9%99%8D%20%2B%20%E7%84%A6%E9%9D%A2%E6%85%A2%E6%BC%82%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=A('<p><span class="marginnote">浸出测试的接触时间必须接近扫描，而不是把胶在水里泡到平衡。泡到平衡会夸大浸出，引出过厚的面涂，反而伤窗口。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把某胶商标的「零浸出」写成物理定律，也不发明 ASML 镜头寿命小时数。高折射率浸没液体会改分配系数，但未成量产，不在此展开。后课默认：浸没栈包含顶界面策略（面涂或无面涂配方）；换策略要同时重做流体缺陷和 E–D 窗。</p><p>照明 RET 在后面的照明课上另起。面涂不降低 \\(k_1\\)，不替代偶极；它只让 1.35 的水膜在化学上可扫描。</p><p><span class="marginnote">常见误区：面涂越疏水越好。过疏会让面涂与胶的黏附变差、面涂自身的涂布缺陷上升——工作点是「浸润够稳」与「隔离够强」的折中，不是往单边极值推。</span></p><p><span class="marginnote">无面涂胶仍可能浸出，只是把合格线做进聚合物。监测不能因为名字叫 topcoat-less 就停掉水质分析。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>水–胶接触让 PAG/淬灭剂浸出：污染镜头，并改表层化学。</li><li>面涂提供隔离与接触角；无面涂路线把隔离写进胶，轨道少一步。</li><li>面涂不是顶上的 BARC；光学厚度要进模型。</li><li>浸出与水印可叠加，分析要拆分子扩散与干燥形貌。</li><li>出处：浸没抗蚀剂化学的公开讨论（leaching / topcoat）；Levinson 对浸没工艺栈的说明；Mack 对 CAR 添加剂的框架。</li></ul>',8))])}const g=s(d,[["render",h]]);export{u as __pageData,g as default};
